--- a/src/main/java/com/blackboard/telemetry/shared/observability/R2dbcAuditTrail.java
+++ b/src/main/java/com/blackboard/telemetry/shared/observability/R2dbcAuditTrail.java
@@ -8,6 +8,10 @@
 @Repository
 public class R2dbcAuditTrail implements AuditTrail {

+    private static final String INSERT_SQL = "INSERT INTO audit_trail "
+            + "(actor, action, outcome, occurred_at, correlation_id) "
+            + "VALUES (:actor, :action, :outcome, :occurredAt, :correlationId)";
+
     private final DatabaseClient databaseClient;

     public R2dbcAuditTrail(DatabaseClient databaseClient) {
@@ -16,6 +20,14 @@

     @Override
     public Mono<Void> record(AuditEntry entry) {
-        return databaseClient.sql("INSERT INTO audit_trail (actor, action, outcome, occurred_at, correlation_id) VALUES (:actor, :action, :outcome, :occurredAt, :correlationId)").bind("actor", entry.actor()).bind("action", entry.action()).bind("outcome", entry.outcome()).bind("occurredAt", entry.timestamp().atOffset(ZoneOffset.UTC)).bind("correlationId", entry.correlationId()).fetch().rowsUpdated().then();
+        return databaseClient.sql(INSERT_SQL)
+                .bind("actor", entry.actor())
+                .bind("action", entry.action())
+                .bind("outcome", entry.outcome())
+                .bind("occurredAt", entry.timestamp().atOffset(ZoneOffset.UTC))
+                .bind("correlationId", entry.correlationId())
+                .fetch()
+                .rowsUpdated()
+                .then();
     }
 }
